        LocalDate checkOut = LocalDate.of(2027, 3, 12);
        BigDecimal rate = new BigDecimal("249.90");

        PriceCalculator.PriceResult result = PriceCalculator.calculate(rate, checkIn, checkOut, "STANDARD");

